def retry_fibonacci(n, max_attempts=3, delay=1):
    import time
    for attempt in range(max_attempts):
        try:
            if n < 0:
                raise ValueError("n must be non-negative")
            a, b = 0, 1
            for _ in range(n):
                a, b = b, a + b
            return a
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            time.sleep(delay)

def flatten_sort_unique(lst):
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result
    flat = flatten(lst)
    if len(flat) <= 1:
        return flat
    pivot = flat[len(flat)//2]
    left = [x for x in flat if x < pivot]
    mid = [x for x in flat if x == pivot]
    right = [x for x in flat if x > pivot]
    return flatten_sort_unique(left) + mid + flatten_sort_unique(right)

def prime_retry(func, max_attempts=3, delay=1, divisor_check=False):
    import time
    for attempt in range(max_attempts):
        try:
            result = func()
            if divisor_check and result is not None:
                n = result
                if n >= 2:
                    for i in range(2, int(n**0.5)+1):
                        if n % i == 0:
                            raise ValueError(f"{n} is not prime")
            return result
        except Exception as e:
            if attempt == max_attempts - 1:
                raise
            time.sleep(delay)
